patch:
diff --git a/repro/no-unused-expressions-es3.test.js b/repro/no-unused-expressions-es3.test.js
new file mode 100644
index 0000000..b730527
--- /dev/null
+++ b/repro/no-unused-expressions-es3.test.js
@@ -0,0 +1,24 @@
+"use strict";
+
+const rule = require("../lib/rules/no-unused-expressions");
+const RuleTester = require("../lib/rule-tester/rule-tester");
+
+const ruleTester = new RuleTester();
+
+ruleTester.run("no-unused-expressions (ecmaVersion 3 directives)", rule, {
+	valid: [
+		{
+			code: "'use strict';",
+			languageOptions: { ecmaVersion: 5, sourceType: "script" },
+		},
+		{
+			code: "'use strict';",
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+		},
+		{
+			code: "function f() { 'use strict'; return 1; }",
+			languageOptions: { ecmaVersion: 3, sourceType: "script" },
+		},
+	],
+	invalid: [],
+});
